/**
 * The server's one access token: taken from LOOSELEAF_TOKEN when set, else
 * read from data/token, else generated and written there (mode 0600).
 */
import { createHash, randomBytes, timingSafeEqual } from 'node:crypto';
import { readFile, writeFile } from 'node:fs/promises';
import { join } from 'node:path';
import { isNotFound } from './doc-log.js';

/** Resolves to the token and whether it was generated by this call. */
export async function loadOrCreateToken(
  dataDir: string,
  fromEnv: string | undefined,
): Promise<{ token: string; generated: boolean; source: string }> {
  if (fromEnv !== undefined && fromEnv.trim() !== '') {
    return { token: fromEnv.trim(), generated: false, source: 'LOOSELEAF_TOKEN' };
  }
  const path = join(dataDir, 'token');
  try {
    const saved = (await readFile(path, 'utf8')).trim();
    if (saved === '') throw new Error(`${path} is empty; delete it to generate a new token or put one in it`);
    return { token: saved, generated: false, source: path };
  } catch (error) {
    if (!isNotFound(error)) throw error;
  }
  const token = randomBytes(32).toString('base64url');
  await writeFile(path, `${token}\n`, { mode: 0o600, flag: 'wx' });
  return { token, generated: true, source: path };
}

/** Compares in constant time; hashing first makes tokens of different lengths comparable. */
export function tokenMatches(given: string, expected: string): boolean {
  const a = createHash('sha256').update(given).digest();
  const b = createHash('sha256').update(expected).digest();
  return timingSafeEqual(a, b);
}

/** The token from an `Authorization: Bearer <token>` header, or null. */
export function bearerToken(header: string | undefined): string | null {
  const match = /^Bearer\s+(.+)$/i.exec(header ?? '');
  return match ? match[1]!.trim() : null;
}
